<p class="muted">Authentication, record changes and administration events. Times are UTC.</p><div class="card table-card"><div class="table-scroll"><table><thead><tr><th>Time</th><th>Actor</th><th>Organization</th><th>Action</th><th>Target</th><th>Details</th></tr></thead><tbody><?php foreach($events as $event): ?><tr><td><?= $e($event['created_at']) ?></td><td><?= $e($event['actor_name']??'System / unauthenticated') ?></td><td><?= $e($event['organization_name']??'—') ?></td><td><?= $e($event['action']) ?></td><td><?= $e($event['target_type'].' '.($event['target_id']??'')) ?></td><td class="audit-details"><?= $e($event['metadata']) ?></td></tr><?php endforeach; ?></tbody></table></div></div><div class="pagination"><?php if($page>1): ?><a href="<?= $link('/audit?page='.($page-1)) ?>">← Previous</a><?php endif; ?><?php if(count($events)===50): ?><a href="<?= $link('/audit?page='.($page+1)) ?>">Next →</a><?php endif; ?></div>
